import type { DesignSystemConfigInput } from '~/types/config'
import {
  resolveTheme,
  colorDeclarations,
  motionThemeDeclarations,
  REDUCED_MOTION_CSS,
  SHADOW_KEYS,
} from '~/utils/themeTokens'

// Generate minimal CSS for plain Tailwind (no component library)
export function generateTailwindCSS(config: DesignSystemConfigInput): string {
  const t = resolveTheme(config)
  const shadows = (mode: 'light' | 'dark') =>
    SHADOW_KEYS.map((k) => `  --shadow-${k}: ${t.shadows[mode][k]};`).join('\n')

  return `@import "tailwindcss";

/*
 * Plain Tailwind CSS v4 theme generated by Vuecraft.
 * Theme variables become utilities (bg-primary, text-muted-foreground,
 * rounded-lg, shadow-md, font-sans ...). Dark values apply under .dark.
 */

@custom-variant dark (&:is(.dark *));

@theme {
${colorDeclarations(t.colors.light, 'color-')}

  --radius: ${t.radius};
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);

  --font-sans: ${t.fontSans};
  --font-heading: ${t.fontHeading};
  --font-mono: ${t.fontMono};

${shadows('light')}

  --default-transition-duration: ${t.animationDuration};
${motionThemeDeclarations(t)}
}

.dark {
${colorDeclarations(t.colors.dark, 'color-')}
${shadows('dark')}
}

@layer base {
  * {
    border-color: var(--color-border);
  }

  body {
    background-color: var(--color-background);
    color: var(--color-foreground);
    font-family: var(--font-sans);
    line-height: ${t.bodyLineHeight};
  }

  h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-heading);
    font-weight: ${t.headingWeight};
  }
}

${REDUCED_MOTION_CSS}
`
}

// Generate setup instructions for plain Tailwind
export function generateTailwindSetupScript(config: DesignSystemConfigInput): string {
  const isNuxt = config.export.framework === 'nuxt'

  if (isNuxt) {
    return `#!/bin/bash

# Tailwind CSS v4 Setup for Nuxt
# Generated by Vuecraft

# Create new Nuxt project
npx nuxi@latest init my-app
cd my-app

# Install Tailwind CSS v4
npm install tailwindcss @tailwindcss/vite

# Add Tailwind to your Nuxt config (nuxt.config.ts):
# vite: {
#   plugins: [tailwindcss()]
# }

# Copy the generated CSS to assets/css/main.css
# Import it in your nuxt.config.ts:
# css: ['~/assets/css/main.css']

# Start development
npm run dev
`
  }

  return `#!/bin/bash

# Tailwind CSS v4 Setup for Vue
# Generated by Vuecraft

# Create new Vue project
npm create vue@latest my-app
cd my-app

# Install Tailwind CSS v4
npm install tailwindcss @tailwindcss/vite

# Add Tailwind to your Vite config (vite.config.ts):
# import tailwindcss from '@tailwindcss/vite'
# plugins: [vue(), tailwindcss()]

# Copy the generated CSS to src/assets/main.css
# Import it in your main.ts

# Start development
npm run dev
`
}

// Generate full export package for plain Tailwind
export function generateTailwindExportPackage(config: DesignSystemConfigInput): {
  css: string
  setupScript: string
  readme: string
} {
  const css = generateTailwindCSS(config)
  const setupScript = generateTailwindSetupScript(config)

  const readme = `# Plain Tailwind CSS Theme

This theme was generated using Vuecraft.

## Configuration

- **Primary Color**: ${config.theme.accentTheme}
- **Base Color**: ${config.theme.baseColor}
- **Border Radius**: ${config.theme.radius}
- **Shadow Intensity**: ${config.theme.shadowIntensity}
- **Font Family**: ${config.typography.fontFamily}
- **Mono Font**: ${config.typography.monoFontFamily}

## Installation

### For ${config.export.framework === 'nuxt' ? 'Nuxt' : 'Vue (Vite)'}

1. Install Tailwind CSS v4:
   \`\`\`bash
   npm install tailwindcss @tailwindcss/vite
   \`\`\`

2. ${config.export.framework === 'nuxt' ? 'Add to your nuxt.config.ts' : 'Add to your vite.config.ts'}:
   \`\`\`typescript
   import tailwindcss from '@tailwindcss/vite'

   // In plugins array:
   plugins: [tailwindcss()]
   \`\`\`

3. Copy \`main.css\` to your assets folder

4. Import the CSS in your app

## Usage

The theme provides CSS variables that work with Tailwind CSS v4:

\`\`\`html
<!-- Use with Tailwind classes -->
<div class="bg-background text-foreground">
  <button class="bg-primary text-primary-foreground rounded-lg">
    Click me
  </button>
</div>

<!-- Or use CSS variables directly -->
<style>
.custom-element {
  background: var(--color-primary);
  border-radius: var(--radius-lg);
}
</style>
\`\`\`

## Available Variables

### Colors
- \`--color-background\` / \`--color-foreground\`
- \`--color-primary\` / \`--color-primary-foreground\`
- \`--color-secondary\` / \`--color-secondary-foreground\`
- \`--color-accent\` / \`--color-accent-foreground\`
- \`--color-muted\` / \`--color-muted-foreground\`
- \`--color-border\`, \`--color-input\`, \`--color-ring\`
- \`--color-destructive\` / \`--color-destructive-foreground\`
- \`--color-chart-1\` through \`--color-chart-5\`

### Layout
- \`--radius-sm\`, \`--radius-md\`, \`--radius-lg\`, \`--radius-xl\`
- \`--shadow-sm\`, \`--shadow-md\`, \`--shadow-lg\`, \`--shadow-xl\`

### Typography
- \`--font-sans\`
- \`--font-heading\`
- \`--font-mono\`

## Files Included

- \`main.css\` - Theme CSS with Tailwind CSS v4 configuration
- \`setup.sh\` - Installation script
`

  return { css, setupScript, readme }
}
